// Assert that there is no de-serialization error when de-serializing
// from `source`.
func assertNoDeserializationError(
	t *testing.T,
	err error,
	source string,
) (ok bool) {
	ok = true
	if err != nil {
		ok = false
		t.Fatalf(
			"Expected no de-serialization error from %s, but got: %s",
			source, err.Error(),
		)
		return
	}
	return
}

// Assert that there is no serialization error when serializing the instance
// originally coming from `source`.
func assertNoSerializationError(
	t *testing.T,
	err error,
	source string,
) (ok bool) {
	ok = true
	if err != nil {
		ok = false
		t.Fatalf(
			"Expected no serialization error when serializing "+
				"the instance obtained from %s, but got: %s",
			source, err.Error(),
		)
		return
	}
	return
}

// Assert that serializing and de-serializing preserves the original instance.
func assertSerializationEqualsDeserialization(
	t *testing.T,
	that ourtypes.IClass,
	other string,
	source string,
) (ok bool) {
	decoder := xml.NewDecoder(strings.NewReader(other))
	roundTripped, err := ourxmlization.Unmarshal(decoder)
	if !assertNoDeserializationError(t, err, source) {
		return false
	}

	if !ourtesting.DeepEqual(that, roundTripped) {
		t.Fatalf("XML round-trip changed the instance from %s", source)
		return false
	}

	return true
}

// Assert that there is a de-serialization error.
//
// If [ourtesting.RecordMode] is set, the de-serialization error is re-recorded
// to `expectedPth`. Otherwise, the error is compared against the golden file
// `expectedPth`.
func assertIsDeserializationErrorAndEqualsExpectedOrRecord(
	t *testing.T,
	err error,
	source string,
	expectedPth string,
) (ok bool) {
	ok = true

	if err == nil {
		ok = false
		t.Fatalf("De-serialization error expected from %s, but got none", source)
		return
	}

	deseriaErr, is := err.(*ourxmlization.DeserializationError)
	if !is {
		ok = false
		t.Fatalf(
			"Expected a de-serialization error, "+
				"but got an error of type %T from %s: %v",
			err, source, err,
		)
		return
	}

	// Add a new line for POSIX systems.
	got := deseriaErr.Error() + "\n"

	if ourtesting.RecordMode {
		parent := filepath.Dir(expectedPth)
		err := os.MkdirAll(parent, os.ModePerm)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to create the directory %s: %s", parent, err.Error(),
				),
			)
		}

		err = os.WriteFile(expectedPth, []byte(got), 0644)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to write to the file %s: %s", expectedPth, err.Error(),
				),
			)
		}
	} else {
		_, err := os.Stat(expectedPth)
		if err != nil {
			ok = false
			t.Fatalf(
				"Failed to stat the file %s: %s; if the file does not exist, "+
					"you probably want to record the test data by "+
					"setting the environment variable %s",
				expectedPth, err.Error(), ourtesting.RecordModeEnvironmentVariableName,
			)
			return
		}

		bb, err := os.ReadFile(expectedPth)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to read from file %s: %s", expectedPth, err.Error(),
				),
			)
		}

		expected := string(bb)

		// NOTE (mristin):
		// Git automatically strips and adds `\r`, so we have to remove it here
		// to obtain a canonical text.
		expected = strings.Replace(expected, "\r", "", -1)

		if expected != got {
			ok = false
			t.Fatalf(
				"What we got differs from the expected in %s. "+
					"We got:\n%s\nWe expected:\n%s",
				expectedPth, got, expected,
			)
			return
		}
	}

	return
}

